// 上游：Extract from File1 的全部行
const rows = $input.all().map((i) => i.json);

function cell(row, key) {
  const v = row?.[key];
  if (v == null || v === '') return '';
  return String(v).trim();
}

function excelTime(v) {
  if (typeof v === 'number' && v > 0 && v < 1) {
    const mins = Math.round(v * 24 * 60);
    const h = String(Math.floor(mins / 60)).padStart(2, '0');
    const m = String(mins % 60).padStart(2, '0');
    return `${h}:${m}`;
  }
  return v == null || v === '' ? '' : String(v).trim();
}

function num(v) {
  const n = Number(v);
  return Number.isFinite(n) ? n : null;
}

function stripCategory(raw) {
  return String(raw || '')
    .replace(/^\d+\s*[.、．]\s*/, '')
    .trim();
}

function fmtMoney(n) {
  if (!Number.isFinite(n)) return '';
  return Number.isInteger(n) ? String(n) : n.toFixed(2);
}

// —— 固定区：index 1~5 ——
// 0=表头，1=活动名称，2=人数，3=活动天数，4=执行日期，5=出发地目的地
const 活动名称 = cell(rows[1], '__EMPTY_1');
const 人数 = num(rows[2]?.['__EMPTY_1']) ?? cell(rows[2], '__EMPTY_1');
const 活动天数 = cell(rows[3], '__EMPTY_1');
const 执行日期 = cell(rows[4], '__EMPTY_1');
const od = cell(rows[5], '__EMPTY_1');
const [出发地, 目的地] = od.split(/[-—–～~]/).map((s) => s.trim());

// —— 定位「活动总价」行 ——
const totalIdx = rows.findIndex((r, i) => {
  if (i <= 5) return false;
  const a = cell(r, 'QUJIA趣加团建');
  return a.includes('活动总价');
});
if (totalIdx < 0) {
  throw new Error('未找到含「活动总价」的行');
}

const totalRow = rows[totalIdx];
const 活动总价 =
  num(totalRow['__EMPTY_2']) ??
  num(totalRow['__EMPTY_1']) ??
  num(totalRow['__EMPTY_4']);

// —— 明细区：6 ~ totalIdx-1（跳过表头「物品名称」行）——
const feeLines = [];
const feeObjects = [];
let category = '';

for (let i = 6; i < totalIdx; i++) {
  const r = rows[i];
  const a = cell(r, 'QUJIA趣加团建');
  const name = cell(r, '__EMPTY');
  // 去掉表格里的换行，并压缩多余空白
  const desc = cell(r, '__EMPTY_1')
    .replace(/[\r\n]+/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
  const qty = r['__EMPTY_2'];
  const price = r['__EMPTY_3'];
  const total = r['__EMPTY_4'];

  if (a && /^\d+\s*[.、．]/.test(a)) {
    category = stripCategory(a);
  }

  // 跳过列头 / 空行 / 零金额行
  if (name === '物品名称' || desc === '描述') continue;
  if (!name && !desc) continue;

  const qtyN = num(qty);
  const priceN = num(price);
  const totalN = num(total);
  if (totalN === 0) continue;

  const itemName = name || '(未命名)';
  const calc =
    qtyN != null && priceN != null
      ? `${fmtMoney(qtyN)}*${fmtMoney(priceN)}=${fmtMoney(totalN ?? qtyN * priceN)}`
      : totalN != null
        ? fmtMoney(totalN)
        : '';

  // 交通： 大巴车（55座）	1*4800=4800		描述
  const md = `${category || '费用'}： ${itemName}\t${calc}\t\t${desc}`;
  feeLines.push(md);
  feeObjects.push({
    分类: category || '费用',
    名称: itemName,
    描述: desc,
    数量: qtyN,
    单价: priceN,
    总价: totalN,
    markdown: md,
  });
}

// —— 行程区：totalIdx 之后 ——
const tripLines = [];
const tripObjects = [];
let day = '';

for (let i = totalIdx + 1; i < rows.length; i++) {
  const r = rows[i];
  const a = cell(r, 'QUJIA趣加团建');
  const b = r['__EMPTY'];
  const c = cell(r, '__EMPTY_1');

  if (a === '活动行程') continue;
  if (a === '日期' && cell(r, '__EMPTY') === '时间') continue;

  if (/^D\d+$/i.test(a)) {
    day = a.toLowerCase().replace(/^d/, 'day');
  }

  const time = excelTime(b);
  const content = c;
  if (!content || content === '内容') continue;

  // day1		10:00-12:00	前往景区
  const md = `${day || '行程'}\t\t${time}\t\t\t${content}`;
  tripLines.push(md);
  tripObjects.push({ day: day || '', 时间: time, 内容: content, markdown: md });
}

// 按「名称 → … → 行程」输出为一个对象数组（下游也可直接取扁平字段）
const extracted = [
  { key: '活动名称', value: 活动名称 },
  { key: '人数', value: 人数 },
  { key: '活动天数', value: 活动天数 },
  { key: '执行日期', value: 执行日期 },
  { key: '出发地目的地', value: od, 出发地: 出发地 || '', 目的地: 目的地 || '' },
  { key: '活动总价', value: 活动总价 },
  { key: '报价明细', value: feeLines.join('\n'), items: feeObjects },
  { key: '活动行程', value: tripLines.join('\n'), items: tripObjects },
];

return [
  {
    json: {
      活动名称,
      人数,
      活动天数,
      执行日期_报价单: 执行日期,
      出发地: 出发地 || '',
      目的地: 目的地 || '',
      出发地目的地: od,
      活动总价,
      报价明细: feeLines.join('\n'),
      活动行程: tripLines.join('\n'),
      报价明细条目: feeObjects,
      活动行程条目: tripObjects,
      extracted, // 名称→行程 的对象数组
    },
  },
];

const quote = $input.first().json; // 节点1 输出

const execFields =
  $('查询待识别执行记录').first().json?.data?.items?.[0]?.fields || {};
const quoteFields =
  $('查询待识报价附件').first().json?.data?.items?.[0]?.fields || {};
const execRecordId =
  $('查询待识别执行记录').first().json?.data?.items?.[0]?.record_id || '';
const orderRecordId =
  $('查询待识报价附件').first().json?.data?.items?.[0]?.record_id || '';

function textOf(v) {
  if (v == null || v === '') return '';
  if (typeof v === 'string' || typeof v === 'number') return String(v).trim();
  if (Array.isArray(v)) return v.map(textOf).filter(Boolean).join('；');
  if (typeof v === 'object') {
    if (Array.isArray(v.value)) return textOf(v.value);
    if (v.text != null) return String(v.text).trim();
    if (v.name != null) return String(v.name).trim();
  }
  return '';
}

function dateOf(v) {
  if (v == null || v === '') return '';
  if (typeof v === 'number') return new Date(v).toISOString().slice(0, 10);
  if (typeof v === 'object' && Array.isArray(v.value) && typeof v.value[0] === 'number') {
    return new Date(v.value[0]).toISOString().slice(0, 10);
  }
  return textOf(v);
}

function fmtYuan(n) {
  const x = Math.round(Number(n) * 100) / 100;
  if (!Number.isFinite(x)) return '0';
  return Number.isInteger(x) ? String(x) : x.toFixed(2);
}

// —— 客户信息：单位 ； 联系人 ； 电话 ——
const customerRaw = textOf(execFields['客户信息']);
const parts = customerRaw.split(/[；;]/).map((s) => s.trim()).filter(Boolean);
const 单位 = parts[0] || textOf(quoteFields['单位']);
const 联系人 = parts[1] || textOf(quoteFields['联系人']);
const 联系方式 = parts[2] || textOf(quoteFields['联系方式']);

// —— 付款比例：如 "2-6-2" → 20% 预付 / 60% 出发前 / 20% 尾款 ——
const payRaw = textOf(execFields['付款比例']); // 也可用表达式写入，但跨节点用 $() 更稳
const totalCost = Number(quote.活动总价);
if (!Number.isFinite(totalCost) || totalCost <= 0) {
  throw new Error(`活动总价无效: ${quote.活动总价}`);
}

const ratios = String(payRaw || '')
  .split(/[-—–_/／]/)
  .map((s) => s.trim())
  .filter(Boolean)
  .map((s) => Number(s));

if (ratios.length < 3 || ratios.some((n) => !Number.isFinite(n))) {
  throw new Error(`付款比例格式无效，期望如 2-6-2，实际: ${payRaw}`);
}

// 单个数字按「成」理解：2 → 20%
const [r1, r2, r3] = ratios;
const p1 = r1 * 10; // %
const p2 = r2 * 10;
const p3 = r3 * 10;
const a1 = (totalCost * p1) / 100;
const a2 = (totalCost * p2) / 100;
const a3 = (totalCost * p3) / 100;

const clauses = [];
if (p1 > 0) {
  clauses.push(
    `甲方于本合同签订之日起三个工作日内支付活动总款的${p1}%作为预付款：${fmtYuan(a1)}元。`,
  );
}
if (p2 > 0) {
  clauses.push(
    `甲方于活动出发前72小时内(出发当天不包含在内)支付活动总款的${p2}%：${fmtYuan(a2)}元，若逾期付款，乙方有权选择单方解除合同，活动将默认取消按照违约情况赔付。`,
  );
}
if (p3 > 0) {
  clauses.push(
    `甲方于活动结束在收到乙方开具的全额发票后，五个工作日内向乙方交纳活动余款${p3}%：${fmtYuan(a3)}元。`,
  );
}

const 付款方式 = clauses.join('\n');

// 行程+费用合并为合同占位符文本
const 活动行程与费用明细 = [
  '一、费用明细',
  quote.报价明细 || '',
  '',
  `活动总价（含税）：${fmtYuan(totalCost)}元`,
  '',
  '二、活动行程',
  quote.活动行程 || '',
].join('\n');

const token = $('获取飞书Token').first().json.tenant_access_token

return [
  {
    json: {
      "tenant_access_token": token,
      "signing_unit": $item("0").$node["拆分item"].json["fields"]["签约单位"]["value"]["0"] ,
      "fields": {
        订单号: textOf(quoteFields['订单号']),
        单位,
        联系人,
        联系方式,
        签约单位: textOf(execFields['签约单位']) || textOf(quoteFields['签约单位']),
        策划师: textOf(execFields['策划']) || textOf(quoteFields['策划师']),
        合同价款: totalCost,
        执行日期:
          dateOf(quoteFields['执行日期']) ||
          dateOf(execFields['执行日期']) ||
          quote.执行日期_报价单 ||
          '',
        活动天数:$input.first().json["活动天数"],
        活动名称: quote.活动名称 || '',
        出发地: quote.出发地 || textOf(quoteFields['出发地']),
        目的地: quote.目的地 || textOf(quoteFields['目的地']),
        执行人数: quote.人数 || textOf(quoteFields['执行人数']),
        付款比例: payRaw,
        付款方式,
        活动行程与费用明细,
        活动费用明细: 活动行程与费用明细, // 兼容 feishu-files-generation config
        执行编号: textOf(execFields['执行编号']),
        执行记录_id: execRecordId,
        订单记录_id: orderRecordId,
        甲方地址: '',
        甲方税号: '',
      },
    },
  },
];

function cleanString(v) {
  if (v === null || v === undefined) return '';
  return String(v).trim();
}

function cleanNumber(v) {
  if (v === null || v === undefined || v === '') return null;
  const n = Number(String(v).replace(/[,，\s]/g, '').trim());
  return Number.isFinite(n) ? n : null;
}

/** yyyy-mm-dd → 飞书日期毫秒时间戳；非法则 null */
function dateToFeishuTimestamp(dateStr) {
  if (!dateStr) return null;
  const s = String(dateStr).trim();
  const m = s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})$/);
  if (!m) return null;
  return new Date(Number(m[1]), Number(m[2]) - 1, Number(m[3])).getTime();
}

const src = $('合同信息聚合').first().json.fields; //传入上游节点的数据
const departure = cleanString(src['出发地']);
const destination = cleanString(src['目的地']);
const execDate = dateToFeishuTimestamp(src['执行日期']);
const activityDays = cleanNumber(src['活动天数']);
const Numberpopulation = src['执行人数'];
const contracturl = {
      "text": $input.first().json.document_name,
      "link": $input.first().json.document_url
};
const status = "成功";

const fields = {};

if (departure) fields['出发地'] = [departure];
if (destination) fields['目的地'] = [destination];
if (execDate !== null) fields['执行日期'] = execDate;
if (activityDays !== null) fields['活动天数'] = activityDays;
if (Numberpopulation !== null) fields['执行人数'] = Numberpopulation;
if (contracturl !== null) fields['电子版合同'] = contracturl;
if (status) fields['合同生成'] = status;

return {
  json: {
    fields
  },
};
